function playNote(freq,when,duration,type="sine",gain=.07){if(!audioCtx||!masterGain)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),when+.025);g.gain.exponentialRampToValueAtTime(.0001,when+duration);o.connect(g);g.connect(masterGain);o.start(when);o.stop(when+duration+.04)}
function soundStep(){if(!musicOn||!audioCtx)return;const now=audioCtx.currentTime,p=soundPresets[activePreset]||soundPresets[0],mode=p[3],vol=(+$ ("#volume").value||0)/100,chord=scales[Math.floor(activePreset/4)%scales.length];if(masterGain)masterGain.gain.setTargetAtTime(vol,now,.12);const note=chord[(step*(activePreset%3+1))%4];if(mode==="piano"){playNote(note,now,.95,"triangle",.095);if(step%4===0)playNote(chord[0]/2,now,.9,"sine",.055);if(step%3===0)playNote(chord[(step+2)%4]*2,now,.28,"sine",.018)}else if(mode==="guitar"){playNote(note,now,.42,"triangle",.085);playNote(note*2,now,.19,"sine",.022);if(step%4===0)playNote(chord[0]/2,now,.75,"sine",.035)}else if(mode==="lofi"){playNote(note,now,.7,"triangle",.075);if(step%2===0)playNote(58+(activePreset%5)*5,now,.09,"sine",.018);if(step%4===0)playNote(chord[0]/2,now,.7,"sine",.045)}else{playNote(chord[step%4]/2,now,1.6,"sine",.035);playNote(chord[(step+2)%4]*2,now,1.1,"sine",.012);playNote(chord[(step+1)%4]*1.5,now,.8,"triangle",.009)}step++;}
function modeDelay(){return soundPresets[activePreset]?.[3]==="ambient"?1150:760}
