$("#audio").onclick=toggleMusic;$("#playmusic").onclick=toggleMusic;$("#track").onchange=()=>{const m=$("#track").value;const key=m==="science"?"ambient":m;const i=soundPresets.findIndex(p=>p[3]===key);if(i>=0)selectPreset(i);if(musicOn){clearInterval(musicTimer);step=0;soundStep();musicTimer=setInterval(soundStep,modeDelay())}};$("#volume").oninput=()=>{if(masterGain&&audioCtx)masterGain.gain.setTargetAtTime((+$ ("#volume").value||0)/100,audioCtx.currentTime,.08)};$("#subject-music-toggle").onclick=toggleMusic;$("#subject-track").onchange=()=>{const m=$("#subject-track").value;const key=m==="science"?"ambient":m;const i=soundPresets.findIndex(p=>p[3]===key);if(i>=0)selectPreset(i);if(musicOn){clearInterval(musicTimer);step=0;soundStep();musicTimer=setInterval(soundStep,modeDelay())}};
