function renderSyllabus(){const root=$("#syllabus-list");if(!root)return;root.innerHTML='';syllabus[activeSyllabusSubject].forEach((item,i)=>{const id=`neet-${activeSyllabusSubject}-${i}`;const label=document.createElement('label');label.className='syllabus-unit';const check=document.createElement('input');check.type='checkbox';check.checked=localStorage.getItem(id)==='1';check.addEventListener('change',()=>{localStorage.setItem(id,check.checked?'1':'0');updateSyllabusProgress()});const wrap=document.createElement('span');wrap.innerHTML=`<strong>${item[0]}</strong><small>${item[1]}</small>`;label.append(check,wrap);root.append(label)});$$("[data-syl-subject]").forEach(b=>b.classList.toggle('active',b.dataset.sylSubject===activeSyllabusSubject));updateSyllabusProgress();Object.entries(syllabus).forEach(([s,items])=>{const el=$("#"+s+"-syl-count");if(el){const done=items.filter((_,i)=>localStorage.getItem(`neet-${s}-${i}`)==='1').length;el.textContent=`${done}/${items.length}`}})}
function updateSyllabusProgress(){const all=Object.entries(syllabus).flatMap(([s,items])=>items.map((_,i)=>localStorage.getItem(`neet-${s}-${i}`)==='1'));const done=all.filter(Boolean).length,total=all.length;const count=$("#syllabus-count");if(count)count.textContent=`${done} / ${total} topics completed`;const fill=$("#syllabus-progress-fill");if(fill)fill.style.width=`${total?done/total*100:0}%`}
