function rocketNavigate(s){const launch=document.createElement('div');launch.className='rocket-transition';launch.innerHTML=`<div class="launch-stars"></div><div class="launch-rocket">🚀</div><div class="launch-label">LAUNCHING ${s.toUpperCase()} WORLD</div><div class="launch-track"><i></i></div>`;document.body.append(launch);document.body.classList.add('launching');setTimeout(()=>{launch.classList.add('blast');},80);setTimeout(()=>{launch.remove();document.body.classList.remove('launching');openSubject(s);const title=$('#immersive-title');if(title)title.scrollIntoView({behavior:'smooth',block:'start'});},1050)}
