function atomMarkup(formula,idx){const atoms=(formula.match(/[A-Z][a-z]?/g)||['C','H','O']).slice(0,8);const palette={H:'#d9eaff',C:'#5d718e',O:'#ff6f91',N:'#6c9bff',Cl:'#83d9a4',Na:'#e5b86c',S:'#f1d36a',P:'#d7a0ff',Br:'#d17b5e',Mg:'#b4c4d7',Ca:'#e7d6a7',Fe:'#d48a61'};return `<div class="molecule-3d" style="--spin:${(idx%4+1)*8}s">${atoms.map((a,i)=>`<span class="atom3d" style="--x:${Math.cos(i*2.4+idx)*70}px;--y:${Math.sin(i*2.4+idx)*46}px;--z:${Math.sin(i*1.7)*42}px;--atom:${palette[a]||'#c1a4ff'};--delay:${i*.12}s">${a}</span>`).join('')}${atoms.slice(1).map((_,i)=>`<i class="bond3d" style="--bond-angle:${i*360/Math.max(1,atoms.length-1)}deg"></i>`).join('')}</div>`}
function chemistryStudio(){const host=$('#immersive-content');const alcohols=[['Methanol','CH₃OH','CH₄O','1 carbon · hydroxyl group'],['Ethanol','CH₃CH₂OH','C₂H₆O','IUPAC: ethanol · CH₃–CH₂–OH'],['Propan-1-ol','CH₃CH₂CH₂OH','C₃H₈O','OH on carbon 1'],['Propan-2-ol','CH₃CHOHCH₃','C₃H₈O','OH on carbon 2'],['Butan-1-ol','CH₃CH₂CH₂CH₂OH','C₄H₁₀O','Straight chain · OH on carbon 1'],['2-methylpropan-1-ol','(CH₃)₂CHCH₂OH','C₄H₁₀O','Branched alcohol']];host.innerHTML=`<div class="studio-toolbar"><span class="studio-pill">50 REACTION CARDS</span><input id="reaction-search" placeholder="Search reaction, alcohol or equation…"><select id="reaction-filter"><option value="all">All reaction types</option>${[...new Set(reactionData.map(r=>r[2]))].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="alcohol-feature"><div class="alcohol-model">${atomMarkup('C2H6O',2)}<div class="model-orbit"></div><span class="model-caption">ROTATING 3D-INSPIRED MODEL</span></div><div><p class="eyebrow">ORGANIC CHEMISTRY · ALCOHOLS</p><h4>Alcohols: IUPAC + 3D bonds</h4><p class="muted">An alcohol contains a hydroxyl group (–OH) attached to a saturated carbon. The model is schematic; atom positions are not a measured molecular geometry.</p><div class="alcohol-grid">${alcohols.map(a=>`<button class="alcohol-card" data-alcohol="${a[0]}"><b>${a[0]}</b><code>${a[1]}</code><small>${a[2]} · ${a[3]}</small></button>`).join('')}</div><p id="alcohol-detail" class="alcohol-detail">Selected example: <b>Ethanol</b> — preferred IUPAC name <b>ethanol</b>; structure CH₃–CH₂–OH. The C–O and O–H bonds are covalent single bonds.</p></div></div><div class="reaction-grid" id="reaction-grid">${reactionData.map((r,i)=>`<article class="reaction-card" data-type="${r[2]}" data-search="${(r.join(' ')).toLowerCase()}"><div class="reaction-top"><span>REACTION ${(i+1).toString().padStart(2,'0')}</span><span>${r[2]}</span></div>${atomMarkup(r[1],i)}<h4>${r[0]}</h4><p class="reaction-equation">${r[1]}</p><small>Model: schematic atoms and bonds · Check conditions in your NCERT text.</small></article>`).join('')}</div>`;
const search=$('#reaction-search'),filter=$('#reaction-filter');function apply(){const q=search.value.toLowerCase(),t=filter.value;$$('.reaction-card').forEach(c=>c.hidden=!(c.dataset.search.includes(q)&&(t==='all'||c.dataset.type===t)))}search.addEventListener('input',apply);filter.addEventListener('change',apply);$$('.alcohol-card').forEach(b=>b.onclick=()=>{const a=alcohols.find(x=>x[0]===b.dataset.alcohol);$$('.alcohol-card').forEach(x=>x.classList.toggle('active',x===b));$('#alcohol-detail').innerHTML=`Selected example: <b>${a[0]}</b> — condensed structure <b>${a[1]}</b>; molecular formula <b>${a[2]}</b>. ${a[3]}. The rotating atom model is illustrative, not a precise molecular geometry.`})}

